INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.62.0',
  '2026-07-31',
  'Расширение скачивается с сайта — отдельно для Chrome и Firefox; защита от подбора токенов',
  E'Расширение больше не нужно собирать руками: в Настройках → «Токены доступа» появились кнопки «⬇️ Для Chrome» и «⬇️ Для Firefox». Каждый архив уже содержит нужный манифест (копировать файлы не надо) и адрес этого приложения — распаковали и загрузили в браузер. Скачивание идёт с нашего домена, а не с GitHub.\n\nДобавлена защита от подбора токенов: после нескольких неудачных попыток входа адрес временно блокируется.',
  E'Расширение переехало в backend/internal/extension/files и вшито через go:embed; zip собирается в памяти при первом запросе и кэшируется — архив всегда соответствует задеплоенной версии, бинарники в репозитории не хранятся. В popup.html плейсхолдер {{APP_URL}} подставляется из config.PublicURL (env PUBLIC_URL, дефолт прод-адрес), поэтому скачанное расширение указывает на тот сервер, откуда взято. Раздача: GET /ext/habits-chrome.zip и /ext/habits-firefox.zip — публично, вне tma-авторизации (это только клиент), Cache-Control 1 час. Брутфорс: internal/auth/brute.go — счётчик неудачных Bearer-попыток по IP (окно 5 мин, порог 10, блок 15 мин, предохранитель на 10000 адресов); заблокированный IP не доходит до БД, Wrap отвечает 429 too_many_attempts, включение блокировки пишется в лог WARN; удачный вход сбрасывает счётчик, пустой IP игнорируется. Тесты: 3 на сборку архивов (состав, подстановка адреса, различие манифестов) + 4 на лимитер (порог, окно, сброс после успеха, пустой IP); вживую проверено 9x401 - 429 и скачивание обоих архивов с проверкой содержимого.'
);
